import * as React from "react"
import { forwardRef, createElement, type SVGAttributes, type ForwardRefExoticComponent, type RefAttributes } from "react"
import { cn } from "@/lib/utils"
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-500:oklch(0 0 0 / 0.14);--chatcn-alpha-600:oklch(0 0 0 / 0.2);--chatcn-amber:oklch(0.555 0.125 60);--chatcn-bg:oklch(1 0 0);--chatcn-blue:oklch(0.550 0.180 258);--chatcn-border:var(--chatcn-gray-400);--chatcn-border-strong:var(--chatcn-gray-600);--chatcn-card:oklch(1 0 0);--chatcn-ease-in-out:cubic-bezier(0.77, 0, 0.175, 1);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-ease-out-soft:cubic-bezier(0.25, 0.46, 0.45, 0.94);--chatcn-ease-standard:ease;--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.970 0 0);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-200:oklch(0.950 0 0);--chatcn-gray-400:oklch(0.910 0 0);--chatcn-gray-600:oklch(0.800 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-green:oklch(0.530 0.130 150);--chatcn-press-scale:0.97;--chatcn-press-scale-icon:0.94;--chatcn-primary:var(--chatcn-gray-1000);--chatcn-primary-fg:var(--chatcn-bg);--chatcn-primary-hover:var(--chatcn-gray-900);--chatcn-radius-lg:12px;--chatcn-radius-md:8px;--chatcn-radius-sm:6px;--chatcn-radius-xs:4px;--chatcn-red:oklch(0.560 0.200 27);--chatcn-scrollbar:var(--chatcn-alpha-500);--chatcn-scrollbar-hover:var(--chatcn-alpha-600);--chatcn-shadow-md:0 0 0 1px oklch(0 0 0 / 0.06), 0 2px 4px -1px oklch(0 0 0 / 0.06), 0 8px 16px -4px oklch(0 0 0 / 0.08);--chatcn-shadow-sm:0 0 0 1px oklch(0 0 0 / 0.06), 0 1px 2px -1px oklch(0 0 0 / 0.06), 0 2px 4px oklch(0 0 0 / 0.04);--chatcn-shadow-xs:0 0 0 1px oklch(0 0 0 / 0.08), 0 1px 2px oklch(0 0 0 / 0.04)}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-500:oklch(1 0 0 / 0.16);--chatcn-alpha-600:oklch(1 0 0 / 0.24);--chatcn-amber:oklch(0.800 0.140 74);--chatcn-bg:oklch(0.145 0 0);--chatcn-blue:oklch(0.710 0.140 252);--chatcn-border:var(--chatcn-gray-400);--chatcn-border-strong:var(--chatcn-gray-600);--chatcn-card:oklch(0.175 0 0);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.195 0 0);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-200:oklch(0.225 0 0);--chatcn-gray-400:oklch(0.285 0 0);--chatcn-gray-600:oklch(0.410 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0);--chatcn-green:oklch(0.760 0.150 152);--chatcn-primary:var(--chatcn-gray-1000);--chatcn-primary-fg:var(--chatcn-bg);--chatcn-primary-hover:var(--chatcn-gray-900);--chatcn-red:oklch(0.700 0.175 22);--chatcn-scrollbar:var(--chatcn-alpha-500);--chatcn-scrollbar-hover:var(--chatcn-alpha-600);--chatcn-shadow-md:0 0 0 1px oklch(1 0 0 / 0.09), inset 0 1px 0 oklch(1 0 0 / 0.04), 0 8px 16px -4px oklch(0 0 0 / 0.5);--chatcn-shadow-sm:0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.03), 0 2px 4px oklch(0 0 0 / 0.4);--chatcn-shadow-xs:0 0 0 1px oklch(1 0 0 / 0.08), 0 1px 2px oklch(0 0 0 / 0.4)}.chatcn-focus{}.chatcn-focus:focus-visible{outline: 2px solid var(--chatcn-accent); outline-offset: 2px;}.chatcn-press{transition: transform 150ms var(--chatcn-ease-out);}.chatcn-press:active{transform: scale(var(--chatcn-press-scale)); transition-duration: 100ms;}.chatcn-shimmer{color: transparent; background-image: linear-gradient(90deg, var(--chatcn-fg-subtle) 0%, var(--chatcn-fg-subtle) 40%, var(--chatcn-fg) 50%, var(--chatcn-fg-subtle) 60%, var(--chatcn-fg-subtle) 100%); background-size: 250% 100%; background-clip: text; -webkit-background-clip: text; animation: chatcn-shimmer 1.6s linear infinite;}.chatcn-spin{animation: chatcn-spin 0.8s linear infinite;}.chatcn-scroll{scrollbar-width: thin; scrollbar-color: var(--chatcn-scrollbar) transparent;}.chatcn-scroll:hover{scrollbar-color: var(--chatcn-scrollbar-hover) transparent;}.chatcn-scroll::-webkit-scrollbar{width: 10px; height: 10px;}.chatcn-scroll::-webkit-scrollbar-track, .chatcn-scroll::-webkit-scrollbar-corner{background: transparent;}.chatcn-scroll::-webkit-scrollbar-thumb{background-color: var(--chatcn-scrollbar); background-clip: content-box; border: 3px solid transparent; border-radius: 9999px;}.chatcn-scroll::-webkit-scrollbar-thumb:hover{background-color: var(--chatcn-scrollbar-hover);}@keyframes chatcn-spin { to { transform: rotate(360deg); } }@keyframes chatcn-shimmer { from { background-position: 100% 0; } to { background-position: 0% 0; } }@media (prefers-reduced-motion: reduce){.chatcn-shimmer{animation:none;color:var(--chatcn-fg-subtle);background-image:none}}@media (prefers-reduced-motion: reduce){:root{--chatcn-press-scale:1;--chatcn-press-scale-icon:1;--chatcn-enter-scale:1}}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-queued-messages")) {
  const style = document.createElement("style")
  style.id = "chatcn-queued-messages"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

/** `after-run` waits for the run to finish. `steer` goes in at the next step, mid-run. */
export type QueuedMode = "after-run" | "steer"

export interface QueuedMessage {
  id: string
  text: string
  mode: QueuedMode
  /** `sending` while the runtime delivers it, `failed` when delivery did not work. */
  status?: "queued" | "sending" | "failed"
}

export interface QueuedMessagesProps extends Omit<React.ComponentProps<"section">, "onChange"> {
  /** Controlled queue. Use with `onItemsChange`. */
  items?: QueuedMessage[]
  defaultItems?: QueuedMessage[]
  /** Every edit, reorder, mode change, removal and undo comes through here. */
  onItemsChange?: (items: QueuedMessage[]) => void
  /** Retry a message whose delivery failed. */
  onRetry?: (id: string) => void
  /** How long the undo row stays after a removal. Default 5000 ms; paused while hovered or focused. */
  undoMs?: number
}

interface Tombstone {
  key: string
  items: QueuedMessage[]
  /** Row index where the undo row sits, and where the messages come back. */
  index: number
}

type Row =
  | { kind: "item"; key: string; item: QueuedMessage }
  | { kind: "undo"; key: string; stone: Tombstone }

function buildRows(items: QueuedMessage[], stones: Tombstone[]): Row[] {
  const rows: Row[] = items.map((item) => ({ kind: "item", key: item.id, item }))
  for (const stone of [...stones].sort((a, b) => a.index - b.index)) {
    rows.splice(Math.min(stone.index, rows.length), 0, { kind: "undo", key: stone.key, stone })
  }
  return rows
}

interface UseChatcnPlanReorderOptions {
  /** Keys of the rendered rows, in order. Rows that cannot move (an undo row) still belong here. */
  ids: readonly string[]
  /** Called with the old and new index when a row is dropped or moved with the keyboard. */
  onMove: (from: number, to: number) => void
  /** Ids that have no handle and never move, for example an undo row. Others flow around them. */
  fixed?: readonly string[]
  /** Readable name of a row, for the screen reader announcement. */
  label?: (id: string) => string
  /** Noun for announcements and handle labels. Default "item". */
  noun?: string
  disabled?: boolean
}

interface DragState {
  id: string
  index: number
  pointerId: number
  startY: number
  dy: number
  active: boolean
  target: number
  shift: number
  tops: number[]
  heights: number[]
  handle: HTMLElement
}

const useIsoLayoutEffect = typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

function reducedMotion() {
  return (
    typeof window !== "undefined" &&
    window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true
  )
}

/** The dropped item settles into its slot on the default out curve. */
const SETTLE_TRANSITION = "transform 160ms var(--chatcn-ease-out)"

/** Pointer travel before a press on the handle turns into a drag, so a click still focuses it. */
const DRAG_THRESHOLD = 3

/** Siblings make room on the in-out curve: this is on-screen movement, not an enter. */
const SHIFT_TRANSITION = "transform 200ms var(--chatcn-ease-in-out)"

/**
 * Reorders a vertical list with a pointer drag on a handle and with the arrow keys.
 *
 * The dragged row follows the pointer 1:1 and its siblings slide out of the way with transforms
 * only, so nothing reflows mid-drag. On drop, `onMove` fires, React reorders the DOM, and the row
 * settles from where it was released into its new slot (FLIP). Keyboard moves are instant: the
 * design rules never animate what the keyboard triggers. Insertions and removals by the caller
 * slide the remaining rows into place.
 *
 * Spread `getItemProps(id)` on each row and `getHandleProps(id)` on its grip button. Render
 * `announcement` in a polite live region.
 */
function useChatcnPlanReorder({
  ids,
  onMove,
  fixed,
  label = (id) => id,
  noun = "item",
  disabled = false,
}: UseChatcnPlanReorderOptions) {
  const items = React.useRef(new Map<string, HTMLElement>())
  const refCallbacks = React.useRef(new Map<string, (el: HTMLElement | null) => void>())
  const prevTops = React.useRef(new Map<string, number>())
  const drag = React.useRef<DragState | null>(null)
  const skipFlip = React.useRef(false)
  const settling = React.useRef(new WeakSet<HTMLElement>())
  const focusAfterMove = React.useRef<string | null>(null)
  const [draggingId, setDraggingId] = React.useState<string | null>(null)
  const [announcement, setAnnouncement] = React.useState("")

  const latest = React.useRef({ ids, onMove, label, noun, fixed, disabled })
  latest.current = { ids, onMove, label, noun, fixed, disabled }

  // FLIP: anything whose slot moved since the last commit slides from its old place to the new.
  const key = ids.join("\u0000")
  useIsoLayoutEffect(() => {
    const animate = !skipFlip.current && !reducedMotion()
    skipFlip.current = false
    const next = new Map<string, number>()
    for (const id of ids) {
      const el = items.current.get(id)
      if (!el) continue
      const top = el.offsetTop
      next.set(id, top)
      const before = prevTops.current.get(id)
      if (!animate || before === undefined) continue
      const delta = before - top
      if (Math.abs(delta) < 0.5) continue
      el.style.transition = "none"
      el.style.transform = `translateY(${delta}px)`
      // Read layout so the browser commits the inverted position before we release it.
      void el.offsetHeight
      el.style.transition = SETTLE_TRANSITION
      el.style.transform = ""
      settling.current.add(el)
      const clear = () => {
        settling.current.delete(el)
        el.style.transition = ""
        el.removeEventListener("transitionend", clear)
      }
      el.addEventListener("transitionend", clear)
    }
    prevTops.current = next

    const focusId = focusAfterMove.current
    focusAfterMove.current = null
    if (focusId) {
      const handle = items.current.get(focusId)?.querySelector<HTMLElement>("[data-reorder-handle]")
      if (handle && document.activeElement !== handle) handle.focus()
    }
  }, [key])

  const getItemProps = React.useCallback((id: string) => {
    let ref = refCallbacks.current.get(id)
    if (!ref) {
      ref = (el: HTMLElement | null) => {
        if (el) items.current.set(id, el)
        else items.current.delete(id)
      }
      refCallbacks.current.set(id, ref)
    }
    return { ref, "data-reorder-item": id }
  }, [])

  const announce = (id: string, to: number) => {
    const { ids, label, noun } = latest.current
    setAnnouncement(`Moved ${noun} ${label(id)} to position ${to + 1} of ${ids.length}.`)
  }

  /** Moves with the keyboard: no animation, focus stays on the handle. */
  const moveBy = (id: string, to: number) => {
    const { ids, onMove, fixed } = latest.current
    const from = ids.indexOf(id)
    const clamped = Math.max(0, Math.min(ids.length - 1, to))
    if (from === -1 || clamped === from) return
    if (fixed?.includes(ids[clamped] ?? "")) {
      // Step over a fixed row instead of swapping with it.
      const beyond = clamped + Math.sign(clamped - from)
      if (beyond < 0 || beyond >= ids.length) return
      return moveBy(id, beyond)
    }
    skipFlip.current = true
    focusAfterMove.current = id
    onMove(from, clamped)
    announce(id, clamped)
  }

  const resetStyles = (except?: string) => {
    for (const [id, el] of items.current) {
      if (id === except) continue
      el.style.transition = "none"
      el.style.transform = ""
      // Hand transitions back to the stylesheet once the jump has painted.
      requestAnimationFrame(() => {
        if (!el.style.transform && !settling.current.has(el)) el.style.transition = ""
      })
    }
  }

  const endDrag = (commit: boolean) => {
    const state = drag.current
    drag.current = null
    if (!state) return
    if (state.handle.hasPointerCapture?.(state.pointerId)) {
      state.handle.releasePointerCapture(state.pointerId)
    }
    if (!state.active) return
    setDraggingId(null)
    const { ids, onMove } = latest.current
    const dragged = items.current.get(state.id)
    const target = commit ? state.target : state.index

    if (target === state.index) {
      // Back to where it started.
      resetStyles(state.id)
      if (dragged) {
        dragged.style.transition = reducedMotion() ? "none" : SETTLE_TRANSITION
        dragged.style.transform = ""
      }
      return
    }

    // Remember where everything is on screen right now, so the layout effect can settle the
    // dropped row from the release point. Siblings already sit where their new slots are.
    const tops = new Map<string, number>()
    ids.forEach((id, i) => {
      const el = items.current.get(id)
      if (!el) return
      let offset = 0
      if (id === state.id) offset = state.dy
      else if (i > state.index && i <= target) offset = -state.shift
      else if (i < state.index && i >= target) offset = state.shift
      tops.set(id, el.offsetTop + offset)
    })
    prevTops.current = tops
    resetStyles()
    onMove(state.index, target)
    announce(state.id, target)
  }

  const getHandleProps = (id: string) => {
    const name = label(id)
    return {
      "data-reorder-handle": "",
      "aria-label": `Reorder ${noun} ${name}`,
      "aria-keyshortcuts": "ArrowUp ArrowDown Home End",
      onKeyDown: (event: React.KeyboardEvent<HTMLElement>) => {
        if (latest.current.disabled) return
        const index = latest.current.ids.indexOf(id)
        let to: number | undefined
        if (event.key === "ArrowUp") to = index - 1
        else if (event.key === "ArrowDown") to = index + 1
        else if (event.key === "Home") to = 0
        else if (event.key === "End") to = latest.current.ids.length - 1
        if (to === undefined) return
        event.preventDefault()
        moveBy(id, to)
      },
      onPointerDown: (event: React.PointerEvent<HTMLElement>) => {
        if (latest.current.disabled || event.button !== 0 || drag.current) return
        const { ids } = latest.current
        const index = ids.indexOf(id)
        if (index === -1) return
        const els = ids.map((key) => items.current.get(key))
        if (els.some((el) => !el)) return
        event.currentTarget.setPointerCapture(event.pointerId)
        const tops = els.map((el) => (el as HTMLElement).offsetTop)
        const heights = els.map((el) => (el as HTMLElement).offsetHeight)
        // The room a moved row needs: its height plus the gap the list puts between rows.
        const gap =
          ids.length > 1 ? Math.max(0, (tops[1] ?? 0) - (tops[0] ?? 0) - (heights[0] ?? 0)) : 0
        drag.current = {
          id,
          index,
          pointerId: event.pointerId,
          startY: event.clientY,
          dy: 0,
          active: false,
          target: index,
          shift: (heights[index] ?? 0) + gap,
          tops,
          heights,
          handle: event.currentTarget,
        }
      },
      onPointerMove: (event: React.PointerEvent<HTMLElement>) => {
        const state = drag.current
        if (!state || state.pointerId !== event.pointerId) return
        const raw = event.clientY - state.startY
        if (!state.active) {
          if (Math.abs(raw) < DRAG_THRESHOLD) return
          state.active = true
          setDraggingId(state.id)
        }
        const { ids, fixed } = latest.current
        const last = ids.length - 1
        const top = state.tops[state.index] ?? 0
        const height = state.heights[state.index] ?? 0
        const min = (state.tops[0] ?? 0) - top
        const max = (state.tops[last] ?? 0) + (state.heights[last] ?? 0) - (top + height)
        const dy = Math.max(min, Math.min(max, raw))
        state.dy = dy

        const center = top + height / 2 + dy
        let target = state.index
        for (let i = state.index + 1; i <= last; i++) {
          if (center > (state.tops[i] ?? 0) + (state.heights[i] ?? 0) / 2) target = i
        }
        for (let i = state.index - 1; i >= 0; i--) {
          if (center < (state.tops[i] ?? 0) + (state.heights[i] ?? 0) / 2) target = i
        }
        // A fixed row never moves, so the dragged one cannot land on it.
        while (target !== state.index && fixed?.includes(ids[target] ?? "")) {
          target += target > state.index ? -1 : 1
        }
        state.target = target

        const motion = reducedMotion() ? "none" : SHIFT_TRANSITION
        ids.forEach((key, i) => {
          const el = items.current.get(key)
          if (!el) return
          if (key === state.id) {
            el.style.transition = "none"
            el.style.transform = `translateY(${dy}px)`
            return
          }
          let offset = 0
          if (i > state.index && i <= target) offset = -state.shift
          else if (i < state.index && i >= target) offset = state.shift
          el.style.transition = motion
          el.style.transform = offset ? `translateY(${offset}px)` : ""
        })
      },
      onPointerUp: (event: React.PointerEvent<HTMLElement>) => {
        if (drag.current?.pointerId === event.pointerId) endDrag(true)
      },
      onPointerCancel: (event: React.PointerEvent<HTMLElement>) => {
        if (drag.current?.pointerId === event.pointerId) endDrag(false)
      },
      onLostPointerCapture: (event: React.PointerEvent<HTMLElement>) => {
        if (drag.current?.pointerId === event.pointerId) endDrag(true)
      },
      // Escape during a drag puts the row back.
      onKeyUp: (event: React.KeyboardEvent<HTMLElement>) => {
        if (event.key === "Escape" && drag.current) endDrag(false)
      },
    }
  }

  return { getItemProps, getHandleProps, draggingId, announcement, moveBy }
}

function snippet(text: string, max = 48) {
  const flat = text.replace(/\s+/g, " ").trim()
  return flat.length > max ? `${flat.slice(0, max - 1).trimEnd()}…` : flat
}

/** Returns a copy of `list` with the item at `from` moved to `to`. */
function moveItem<T>(list: readonly T[], from: number, to: number): T[] {
  const next = list.slice()
  const [item] = next.splice(from, 1)
  if (item !== undefined) next.splice(to, 0, item)
  return next
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

export function Button({
  variant = "ghost",
  size = "md",
  type = "button",
  className,
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
export type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
export function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

