function UndoRow({
  stone,
  itemProps,
  undoMs,
  onUndo,
  onExpire,
}: {
  stone: Tombstone
  itemProps: ReturnType<ReturnType<typeof useChatcnPlanReorder>["getItemProps"]>
  undoMs: number
  onUndo: () => void
  onExpire: () => void
}) {
  const [paused, setPaused] = React.useState(false)
  const undoRef = React.useRef<HTMLButtonElement>(null)
  const expire = React.useRef(onExpire)
  expire.current = onExpire

  React.useEffect(() => {
    if (paused) return
    const id = window.setTimeout(() => expire.current(), undoMs)
    return () => window.clearTimeout(id)
  }, [paused, undoMs])

  // Removing with the keyboard puts focus on Undo, so taking it back is one keypress.
  React.useEffect(() => {
    if (document.activeElement === document.body || document.activeElement === null) {
      undoRef.current?.focus({ preventScroll: true })
    }
  }, [])

  const first = stone.items[0]
  const label =
    stone.items.length === 1 && first
      ? `Removed “${snippet(first.text)}”`
      : `Removed ${stone.items.length} messages`

  return (
    <li
      {...itemProps}
      data-slot="queued-undo"
      onPointerEnter={() => setPaused(true)}
      onPointerLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      className={cn(
        "rounded-(--chatcn-radius-sm) flex min-h-10 min-w-0 items-center gap-2 py-1 ps-2 pe-1",
        "ease-(--chatcn-ease-out) transition-opacity duration-150 starting:opacity-0",
      )}
    >
      <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) min-w-0 flex-1 truncate">{label}</span>
      <Button ref={undoRef} size="xs" onClick={onUndo}>
        <RotateCcwIcon aria-hidden="true" />
        Undo
      </Button>
    </li>
  )
}

