function QueuedRow({
  item,
  index,
  count,
  animate,
  dragging,
  itemProps,
  handleProps,
  onChange,
  onRemove,
  onRetry,
}: QueuedRowProps) {
  const [editing, setEditing] = React.useState(false)
  const [draft, setDraft] = React.useState(item.text)
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const textRef = React.useRef<HTMLButtonElement>(null)
  const composing = React.useRef(false)
  const returnFocus = React.useRef(false)
  useChatcnAutoResize(textareaRef, { value: draft, enabled: editing })
  const sending = item.status === "sending"
  const failed = item.status === "failed"
  const locked = sending

  React.useEffect(() => {
    if (!editing) {
      if (returnFocus.current) textRef.current?.focus({ preventScroll: true })
      returnFocus.current = false
      return
    }
    const el = textareaRef.current
    if (!el) return
    el.focus({ preventScroll: true })
    el.setSelectionRange(el.value.length, el.value.length)
  }, [editing])

  const startEdit = () => {
    if (locked) return
    setDraft(item.text)
    setEditing(true)
  }
  const save = () => {
    returnFocus.current = true
    const text = draft.trim()
    setEditing(false)
    if (text.length === 0) onRemove()
    else if (text !== item.text) onChange({ text })
  }
  const cancel = () => {
    returnFocus.current = true
    setEditing(false)
    setDraft(item.text)
  }

  return (
    <li
      {...itemProps}
      data-slot="queued-message"
      data-mode={item.mode}
      data-queued-status={item.status ?? "queued"}
      data-dragging={dragging ? "" : undefined}
      data-editing={editing ? "" : undefined}
      className={cn(
        "group/queued rounded-(--chatcn-radius-sm) bg-(color:--chatcn-card) relative flex min-w-0 items-start gap-0.5 py-1 ps-1 pe-1",
        "hover:bg-(color:--chatcn-fill)/60 focus-within:bg-(color:--chatcn-fill)/60 data-[editing]:bg-(color:--chatcn-fill)",
        dragging && "shadow-(--chatcn-shadow-md) bg-(color:--chatcn-card) hover:bg-(color:--chatcn-card) z-10",
        animate &&
          "ease-(--chatcn-ease-out-soft) transition-[opacity,translate] duration-200 starting:translate-y-1 starting:opacity-0 motion-reduce:starting:translate-y-0",
      )}
    >
      {sending ? (
        <span className="text-(color:--chatcn-blue) grid h-8 w-6 shrink-0 place-items-center pointer-coarse:h-11 pointer-coarse:w-9">
          <Spinner className="size-3.5" />
        </span>
      ) : (
        <ModeToggle value={item.mode} index={index} onChange={(mode) => onChange({ mode })} />
      )}

      <div className="flex min-w-0 flex-1 flex-col">
        {editing ? (
          <textarea
            ref={textareaRef}
            value={draft}
            rows={1}
            aria-label={`Edit queued message ${index + 1}`}
            onChange={(event) => setDraft(event.target.value)}
            onCompositionStart={() => {
              composing.current = true
            }}
            onCompositionEnd={() => {
              window.setTimeout(() => {
                composing.current = false
              }, 0)
            }}
            onKeyDown={(event) => {
              if (isComposing(event, composing.current)) return
              if (event.key === "Enter" && !event.shiftKey) {
                event.preventDefault()
                save()
              } else if (event.key === "Escape") {
                event.preventDefault()
                event.stopPropagation()
                cancel()
              }
            }}
            onBlur={(event) => {
              // Clicking Save or Cancel handles itself; anywhere else saves, like a note app.
              if (event.relatedTarget?.closest("[data-queued-edit-actions]")) return
              if (editing) save()
            }}
            className={cn(
              "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) max-h-40 min-h-8 w-full resize-none bg-transparent px-1 py-1.5 outline-none",
              "chatcn-scroll field-sizing-content overflow-y-auto",
            )}
          />
        ) : (
          <button
            ref={textRef}
            type="button"
            onClick={startEdit}
            onKeyDown={(event) => {
              if ((event.key === "Backspace" || event.key === "Delete") && !locked) {
                event.preventDefault()
                onRemove()
              }
            }}
            aria-label={`Queued message ${index + 1} of ${count}: ${item.text}. ${MODE_TEXT[item.mode]}. Press Enter to edit, Delete to remove.`}
            disabled={locked}
            className={cn(
              "chatcn-focus rounded-(--chatcn-radius-xs) text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-h-8 w-full px-1 py-1.5 text-start",
              "text-pretty [overflow-wrap:anywhere]",
              sending
                ? "text-(color:--chatcn-fg-subtle) cursor-default"
                : "text-(color:--chatcn-fg-muted) hover:text-(color:--chatcn-fg) cursor-text",
              "ease-(--chatcn-ease-standard) transition-colors duration-150",
            )}
          >
            <span className="line-clamp-2">{item.text}</span>
          </button>
        )}
        {failed && !editing ? (
          <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-red) min-h-5 px-1 pb-1 text-pretty">
            Not delivered. Check your connection, then retry.
          </p>
        ) : null}
      </div>

      {editing ? (
        <div data-queued-edit-actions="" className="flex h-8 shrink-0 items-center gap-1">
          <Button size="xs" onClick={cancel}>
            Cancel
          </Button>
          <Button size="xs" variant="solid" onClick={save}>
            Save
          </Button>
        </div>
      ) : (
        <div className="flex h-8 shrink-0 items-center gap-0.5">
          {sending ? (
            // The row's edit and remove actions leave while it sends, so the label takes the
            // trailing edge every other row's last action sits on.
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) px-2 tabular-nums">
              {item.mode === "steer" ? "Steering" : "Sending"}
            </span>
          ) : failed && onRetry ? (
            <Tooltip content="Retry">
              <Button
                size="xs"
                variant="outline"
                aria-label={`Retry message ${index + 1}`}
                onClick={onRetry}
              >
                <RotateCcwIcon aria-hidden="true" />
                {/* Narrow queues keep the room for the message; the icon still says retry. */}
                <span className="hidden @[26rem]/queue:inline">Retry</span>
              </Button>
            </Tooltip>
          ) : null}
          <span
            className={cn(
              "ms-1 flex items-center gap-0.5",
              // Always there, faint until the row is in use: nothing jumps and nothing hides.
              "[&_button]:text-(color:--chatcn-fg-faint) group-focus-within/queued:[&_button]:text-(color:--chatcn-fg-subtle) group-hover/queued:[&_button]:text-(color:--chatcn-fg-subtle)",
              sending && "hidden",
            )}
          >
            <Tooltip content="Edit">
              <Button
                size="icon-xs"
                aria-label={`Edit message ${index + 1}`}
                onClick={startEdit}
                className="pointer-coarse:size-11"
              >
                <PencilIcon />
              </Button>
            </Tooltip>
            <Tooltip content="Remove">
              <Button
                size="icon-xs"
                aria-label={`Remove message ${index + 1}`}
                onClick={onRemove}
                className="pointer-coarse:size-11"
              >
                <Trash2Icon />
              </Button>
            </Tooltip>
            <button
              type="button"
              {...handleProps}
              disabled={count < 2}
              className={cn(
                "chatcn-focus rounded-(--chatcn-radius-xs) grid h-8 w-5 cursor-grab touch-none place-items-center active:cursor-grabbing",
                "hover:text-(color:--chatcn-fg) ease-(--chatcn-ease-standard) transition-colors duration-150",
                "disabled:invisible pointer-coarse:h-11 pointer-coarse:w-8",
              )}
            >
              <GripVerticalIcon aria-hidden="true" className="size-4" />
            </button>
          </span>
        </div>
      )}
    </li>
  )
}

