                <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">{task}</p>
              </div>
            ) : null}
            {children ?? (steps && steps.length > 0 ? <SubagentSteps steps={steps} /> : null)}
