                </Button>
              </div>
            ) : null}
          </div>
        </Collapsible.Panel>
      ) : null}
      <span aria-live="polite" className="sr-only">
        {settled
          ? `${typeof name === "string" ? name : "Subagent"} ${STATUS_TEXT[status].toLowerCase()}`
          : ""}
      </span>
    </Collapsible.Root>
  )
}

