/**
 * The agent works in steps. Steering messages go in at the next step; the rest wait for the run
 * to finish. Type below to add to the queue while it works.
 */
function QueuedMessagesDemo() {
  const [queue, setQueue] = React.useState(SEED)
  const [step, setStep] = React.useState(0)
  const [delivered, setDelivered] = React.useState<string[]>([])
  const [draft, setDraft] = React.useState("")
  const running = step < ACTIVITY.length
  const queueRef = React.useRef(queue)
  queueRef.current = queue

  // Each step boundary delivers steering messages; the end of the run delivers the rest.
  React.useEffect(() => {
    const id = window.setTimeout(
      () => {
        const boundary = running
        const due = queueRef.current.filter(
          (m) => (boundary ? m.mode === "steer" : true) && m.status !== "sending",
        )
        if (due.length > 0) {
          const ids = new Set(due.map((m) => m.id))
          setQueue((q) => q.map((m) => (ids.has(m.id) ? { ...m, status: "sending" } : m)))
          window.setTimeout(() => {
            setQueue((q) => q.filter((m) => !ids.has(m.id)))
            setDelivered((d) => [...d, ...due.map((m) => m.text)].slice(-3))
          }, 700)
        }
        setStep((s) => (s >= ACTIVITY.length + 2 ? 0 : s + 1))
      },
      running ? 3200 : 2400,
    )
    return () => window.clearTimeout(id)
  }, [step, running])

  const submit = () => {
    const text = draft.trim()
    if (!text) return
    counter += 1
    setQueue((q) => [...q, { id: `new-${counter}`, text, mode: "after-run" }])
    setDraft("")
  }
  const keys = useChatcnImeSubmit({ onSubmit: submit, submitOn: "enter" })

  return (
    <TooltipProvider>
      <div className="flex w-full max-w-2xl flex-col gap-3">
        <div className="flex min-h-24 flex-col justify-end gap-2">
          {delivered.map((text, i) => (
            <p
              key={`${i}-${text}`}
              className="bg-(color:--chatcn-fill) text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) rounded-(--chatcn-radius-lg) ms-auto max-w-[80%] px-3.5 py-2 text-pretty transition-[opacity,translate] duration-200 starting:translate-y-1 starting:opacity-0 motion-reduce:starting:translate-y-0"
            >
              {text}
            </p>
          ))}
          <Subagent
            name="Coding agent"
            status={running ? "running" : "done"}
            activity={ACTIVITY[Math.min(step, ACTIVITY.length - 1)]}
            summaryLine="Run finished. Delivering queued messages."
            toolCount={Math.min(step + 1, ACTIVITY.length)}
          />
        </div>
        <QueuedMessages items={queue} onItemsChange={setQueue} />
        <div className="rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) focus-within:shadow-(--chatcn-shadow-sm) flex items-center gap-2 py-2 ps-4 pe-2">
          <textarea
            value={draft}
            rows={1}
            onChange={(e) => setDraft(e.target.value)}
            {...keys}
            placeholder="Add to the queue while the agent works…"
            aria-label="Message"
            className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) placeholder:text-(color:--chatcn-fg-subtle) field-sizing-content max-h-32 min-w-0 flex-1 resize-none bg-transparent py-1.5 outline-none"
          />
          <button
            type="button"
            aria-label="Queue message"
            onClick={submit}
            disabled={!draft.trim()}
            className="chatcn-focus chatcn-press bg-(color:--chatcn-fg) text-(color:--chatcn-bg) rounded-(--chatcn-radius-md) grid size-8 shrink-0 place-items-center disabled:opacity-30"
          >
            <ArrowUpIcon className="size-4" />
          </button>
        </div>
      </div>
    </TooltipProvider>
  )
}

